# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMR-000001",
    "name": "Ivan",
    "kind": "first-name",
    "meaning": "Ivan is a masculine given name in Russian. Meaning: God is gracious. The Russian form of John; the classic Russian name."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Iva")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

